func columns(node: Node3D, room: Dictionary) -> void:
	var h := float(room.height)
	var half := FLOOR.size_of(room) * 0.5
	var side: float = OFFICE.COLUMN
	var wide: float = side + COLUMN_PROUD * 2.0
