		if posts.is_empty(): continue
		var id := int(room.id)
		var node: Node3D = hotel.room_nodes[id]
		for r in posts: unique['%.2f,%.2f' % [(r as Rect2).get_center().x, (r as Rect2).get_center().y]] = [r, float(room.py)]
		for piece in node.find_children('Column_*', 'MeshInstance3D', false, false):
			pieces += 1
			if (piece as MeshInstance3D).cast_shadow != GeometryInstance3D.SHADOW_CASTING_SETTING_OFF: shadows += 1
		var face: float = float(room.height) + OG.TILE_FACE + OG.TILE_THICK * 0.5
		var runs := runs_of(node, face)
		var rect: Rect2 = OFFICE.ceiling_rect(room)
