				var inside: bool = posts.any(func(r): return (r as Rect2).grow(-0.003).has_point(p))
				var outside: bool = not posts.any(func(r): return (r as Rect2).grow(0.003).has_point(p))
				if not inside and not outside: continue
				var local := p - middle
				var under: int = runs.filter(func(r): return (r as Rect2).has_point(local)).size()
